15.query:
timeseries a0 = avg(aerospike_sets_index_populating, filter: { cluster_name == $cluster and in(service, array($node)) and in(ns, array($namespace)) and in(`set`, array($set)) }), a1 = avg(aerospike_sets_sindexes, filter: { cluster_name == $cluster and in(service, array($node)) and in(ns, array($namespace)) and in(`set`, array($set)) }), by: { cluster_name, ns, service, `set` }
| fieldsAdd indexes_populating = a0[], secondary_indexes = a1[]
| fieldsRemove a0, a1

